{%- assign items = page.items | sort: "date" | reverse -%}
{%- for i in items %}
{%- comment -%}
  Three shapes here: reading items (have `type`, and an external url that may
  be absent), projects (have `status`), and posts. Every entry needs a stable
  unique id, so a url-less reading item falls back to a tag-page fragment.
{%- endcomment -%}
{%- if i.type -%}
  {%- if i.url -%}{%- assign link = i.url -%}
  {%- else -%}
    {%- comment -%}Slugify the title alone: chaining it after the path would
    slugify the slashes and the # too.{%- endcomment -%}
    {%- assign frag = i.title | slugify -%}
    {%- assign link = '/tags/' | append: page.tag | append: '/#' | append: frag | absolute_url -%}
  {%- endif -%}
{%- else -%}
  {%- assign link = i.url | absolute_url -%}
{%- endif %}

