  {%- if i.author %}{{ i.author | xml_escape }}{% endif %}
  {%- if i.note %}{{ i.note | markdownify | xml_escape }}{% endif %}
  {%- elsif i.status %}

  {%- if i.summary %}{{ i.summary | xml_escape }}{% endif %}
  {{ i.content | xml_escape }}
  {%- else %}

  {{ i.content | xml_escape }}
  {%- endif %}
